#[derive(Subcommand, Debug)]
pub enum EntryAction {
    /// Summarize billable time for invoicing, grouped by project.
    #[command(after_long_help = "\
Examples:
  toggl entry invoice
  toggl entry invoice --since 2026-01-01 --until 2026-01-31")]
    Invoice {
        #[arg(long, help = "Filter time entries starting on or after this date/time")]
        since: Option<String>,
        #[arg(long, help = "Filter time entries before this date/time")]
        until: Option<String>,
    },
    /// Show the currently running time entry.
    #[command(
        name = "running",
        alias = "current",
        after_long_help = "\
Examples:
  toggl entry running             Show the running entry
  toggl entry running --json      Show the running entry as JSON

Note: JSON output includes a \"running\": true field for active entries."
    )]
    Current {
use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;
const MINIMUM_ENTRY_SECONDS: i64 = 30 * 60;

pub struct InvoiceCommand;

fn billable_seconds(duration: i64) -> i64 {
    let rounded =
        ((duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS;
    rounded.max(MINIMUM_ENTRY_SECONDS)
}

fn invoice_totals(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();
    for entry in entries
        .iter()
        .filter(|entry| entry.billable && !entry.is_running())
    {
        let project = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| "No Project".to_string());
        *totals.entry(project).or_default() += billable_seconds(entry.duration);
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, total_a), (name_b, total_b)| {
        total_b.cmp(total_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = invoice_totals(&entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
        for (project, seconds) in totals {
            println!("{seconds}s  {project}");
        }
        println!("{total}s  Total");
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::TimeEntry;
    use chrono::Utc;

    fn entry(duration: i64, billable: bool, running: bool, project: Option<&str>) -> TimeEntry {
        TimeEntry {
            id: 1,
            description: String::new(),
            start: Utc::now(),
            stop: (!running).then(Utc::now),
            duration: if running { -1 } else { duration },
            billable,
            workspace_id: 1,
            tags: vec![],
            project: project.map(|name| crate::models::Project {
                id: 1,
                name: name.to_string(),
                workspace_id: 1,
                client: None,
                is_private: false,
                active: true,
                at: Utc::now(),
                created_at: Utc::now(),
                color: String::new(),
                billable: None,
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn rounds_and_applies_minimum_per_entry_before_grouping() {
        let entries = vec![
            entry(1, true, false, Some("Alpha")),
            entry(16 * 60, true, false, Some("Alpha")),
            entry(31 * 60, true, false, Some("Beta")),
            entry(10 * 60, false, false, Some("Ignored")),
            entry(60 * 60, true, true, Some("Ignored")),
            entry(20 * 60, true, false, None),
        ];

        assert_eq!(
            invoice_totals(&entries),
            vec![
                ("Alpha".to_string(), 60 * 60),
                ("Beta".to_string(), 45 * 60),
                ("No Project".to_string(), 30 * 60),
            ]
        );
    }

    #[test]
    fn sorts_ties_alphabetically() {
        let entries = vec![
            entry(30 * 60, true, false, Some("Zulu")),
            entry(30 * 60, true, false, Some("Alpha")),
        ];
        assert_eq!(invoice_totals(&entries)[0].0, "Alpha");
    }
}
    },
}

